return {api_version=1,id="EX1_544",name="Flare",text="All minions lose <b>Stealth</b>. Destroy all enemy <b>Secrets</b>. Draw a card.",set="EXPERT1",type="spell",class="hunter",rarity="rare",cost=1,on_play=function(ctx,self)for _,e in ipairs(ctx:minions())do ctx:disable_keyword(e,"stealth")end;for _,s in ipairs(ctx:secrets(ctx:opponent(ctx:controller(self))))do ctx:reveal_secret(s)end;ctx:draw(ctx:controller(self),1)end}
